package dev.mcpmcp.forge;
import com.google.gson.*;import dev.mcpmcp.core.*;import dev.mcpmcp.api.*;
import net.minecraftforge.fml.ModList;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.security.MessageDigest;import java.net.*;
/** Declarative extensions hot-swap atomically; Java providers load once from locally trusted code. */
public final class PluginManager {
 private final Path root;private final PluginFiles files;private PluginContext context;private String revision="";private JsonArray plugins=new JsonArray();private Map<String,JsonObject> declarations=Map.of();private final Map<String,BinaryAction> binaryActions=new LinkedHashMap<>();private final Map<String,List<Observer>> observers=new LinkedHashMap<>();private final List<URLClassLoader> loaders=new ArrayList<>();private String error;
 private record BinaryAction(JsonObject schema,String transport,String permission,PluginContext.Handler handler){}
 private record Observer(int priority,PluginContext.Handler handler){}
 public PluginManager(Path p){root=p;files=new PluginFiles(p);}
 public void setContext(PluginContext c){context=c;}
 public JsonObject reload(){try{Map<String,JsonObject> next=new LinkedHashMap<>();JsonArray summaries=new JsonArray();MessageDigest digest=MessageDigest.getInstance("SHA-256");List<Path> dirs;try(var stream=Files.list(root)){dirs=stream.filter(p->Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)&&!Files.isSymbolicLink(p)).sorted().limit(257).toList();}if(dirs.size()>256)throw new IllegalArgumentException("plugin_count_limit");for(Path dir:dirs){Path manifest=dir.resolve("plugin.json");if(!Files.exists(manifest))continue;if(Files.size(manifest)>262144)throw new IllegalArgumentException("manifest_too_large");byte[] bytes=Files.readAllBytes(manifest);digest.update(bytes);JsonObject m=JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();Schema.bounded(m);if(Jsons.integer(m,"api",0)!=1)throw new IllegalArgumentException("plugin_api_mismatch");String id=Jsons.str(m,"id","");if(!id.matches("[a-z0-9_.-]{1,96}"))throw new IllegalArgumentException("invalid_plugin_id");String mod=Jsons.str(m,"mod_id","");boolean installed=mod.equals("minecraft")||ModList.get().isLoaded(mod);String status=installed?"active":"target_mod_missing";String expected=Jsons.str(m,"target_sha256","");String actual="";if(installed&&!mod.equals("minecraft")){var info=ModList.get().getModFileById(mod);Path jar=info.getFile().getFilePath();if(Files.isRegularFile(jar)){actual=hash(jar);if(!expected.matches("[a-f0-9]{64}")||!expected.equals(actual))status="target_hash_mismatch";}else status="target_jar_unavailable";}if(!Jsons.str(m,"minecraft","1.20.1").equals("1.20.1")||!Jsons.str(m,"loader","forge").equals("forge"))status="platform_mismatch";
    JsonArray actions=Jsons.array(m,"actions");Path external=dir.resolve("actions.json");if(Files.exists(external)){if(Files.isSymbolicLink(external)||Files.size(external)>262144)throw new IllegalArgumentException("invalid_actions_file");byte[] ab=Files.readAllBytes(external);digest.update(ab);actions=JsonParser.parseString(new String(ab,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray();}
    if(actions.size()>128)throw new IllegalArgumentException("plugin_action_limit");if(status.equals("active"))for(JsonElement a:actions){JsonObject action=a.getAsJsonObject().deepCopy();String name=Jsons.str(action,"name","");if(!name.matches("[a-z0-9_.-]{1,128}")||next.containsKey(name)||Runtime.isBuiltin(name))throw new IllegalArgumentException("plugin_action_name_conflict");if(!Set.of("normal","hack","cheat").contains(Jsons.str(action,"permission","normal")))throw new IllegalArgumentException("invalid_plugin_permission");if(!Jsons.str(action,"transport","packet").equals("packet"))throw new IllegalArgumentException("declarative_actions_require_packet_transport");action.addProperty("plugin_id",id);next.put(name,action);}
    summaries.add(Jsons.obj("id",id,"folder",dir.getFileName().toString(),"mod_id",mod,"status",status,"target_sha256",actual,"declarations_hot_reload",true,"java_present",Files.exists(dir.resolve("adapter.jar")),"java_reload","restart_required"));}
   revision=HexFormat.of().formatHex(digest.digest());declarations=Map.copyOf(next);plugins=summaries;error=null;return Jsons.obj("observed_success",true,"revision",revision,"plugins",plugins,"actions",next.size());
  }catch(Exception e){error=e.getClass().getSimpleName()+": "+Objects.toString(e.getMessage(),"");return Jsons.obj("error","plugin_reload_failed","reason",error,"retained_revision",revision);}}
 public void loadTrustedJavaOnce(){if(!Runtime.config().trustJavaPlugins||context==null)return;for(JsonElement e:plugins){JsonObject p=e.getAsJsonObject();if(!p.get("status").getAsString().equals("active"))continue;Path jar=root.resolve(p.get("folder").getAsString()).resolve("adapter.jar");if(!Files.isRegularFile(jar,LinkOption.NOFOLLOW_LINKS)||Files.isSymbolicLink(jar))continue;try{URLClassLoader loader=new URLClassLoader(new URL[]{jar.toUri().toURL()},McpmcpPlugin.class.getClassLoader());loaders.add(loader);for(McpmcpPlugin plugin:ServiceLoader.load(McpmcpPlugin.class,loader)){plugin.register(new RestrictedContext(plugin.id()));}}catch(Exception|LinkageError ex){p.addProperty("java_error",ex.toString());}}}
 private final class RestrictedContext implements PluginContext {final String owner;RestrictedContext(String owner){this.owner=owner;}public void action(String n,JsonObject s,String t,String p,Handler h){if(Runtime.isBuiltin(n)||declarations.containsKey(n)||binaryActions.containsKey(n))throw new IllegalArgumentException("action_conflict");if(!Set.of("normal","hack","cheat").contains(p)||!Set.of("packet","client","input","baritone").contains(t))throw new IllegalArgumentException("invalid_action_policy");binaryActions.put(n,new BinaryAction(s.deepCopy(),t,p,h));}public void observer(String k,int priority,Handler h){observers.computeIfAbsent(k,x->new ArrayList<>()).add(new Observer(priority,h));observers.get(k).sort(Comparator.comparingInt(Observer::priority).reversed());}public JsonObject execute(String n,JsonObject a){return context.execute(n,a);}public JsonObject observe(String k,JsonObject a){return context.observe(k,a);}}
 public JsonObject status(){return Jsons.obj("plugins",plugins,"revision",revision,"error",error,"java_loaded",loaders.size(),"java_trusted",Runtime.config().trustJavaPlugins,"file_policy","plugin_text_only; no external client file mutation");}
 public boolean hasAction(String n){return declarations.containsKey(n)||binaryActions.containsKey(n);}
 public JsonObject describe(String n){if(declarations.containsKey(n))return declarations.get(n).deepCopy();BinaryAction b=binaryActions.get(n);return b==null?Jsons.error("unknown_plugin_action"):Jsons.obj("name",n,"input_schema",b.schema,"transport",b.transport,"permission",b.permission,"java",true);}
 public JsonObject actions(){JsonArray all=new JsonArray();declarations.values().forEach(a->all.add(a.deepCopy()));binaryActions.keySet().forEach(n->all.add(describe(n)));return Jsons.obj("entries",all,"revision",revision);}
 public JsonObject execute(String n,JsonObject a){JsonObject declaration=describe(n);if(declaration.has("error"))return declaration;String transport=Jsons.str(declaration,"transport","packet"),permission=Jsons.str(declaration,"permission","normal");if(!Policy.allowed(Runtime.config().mode,Runtime.config().transport,transport,permission))return Jsons.error("plugin_policy_denied");if(a.has("plugin_revision")&&!Jsons.str(a,"plugin_revision","").equals(revision))return Jsons.error("plugin_revision_changed");JsonObject parameters=a.deepCopy();parameters.remove("plugin_revision");try{Schema.validate(parameters,Jsons.object(declaration,"input_schema"));BinaryAction b=binaryActions.get(n);if(b!=null)return b.handler.call(parameters);for(JsonElement condition:Jsons.array(declaration,"preconditions"))if(!Actions.condition(bind(condition,parameters).getAsJsonObject()))return Jsons.error("plugin_precondition_failed");JsonObject packet=bind(declaration.get("packet"),parameters).getAsJsonObject();return PacketService.send(packet);}catch(Exception ex){return Jsons.obj("error","plugin_action_failed","reason",ex.toString());}}
 public Optional<JsonObject> observe(String kind,JsonObject args){List<Observer> o=observers.get(kind);if(o==null)return Optional.empty();for(Observer observer:o)try{JsonObject r=observer.handler.call(args.deepCopy());if(r!=null&&!r.has("error"))return Optional.of(r);}catch(Exception ignored){}return Optional.empty();}
 public JsonObject readFile(String path){return Jsons.obj("path",path,"text",files.read(path));}public JsonObject writeFile(String path,String text){files.write(path,text);return Jsons.obj("observed_success",true,"path",path,"reload_required",true);}
 private static JsonElement bind(JsonElement value,JsonObject args){if(value==null)throw new IllegalArgumentException("missing_packet_declaration");if(value.isJsonObject()){JsonObject o=value.getAsJsonObject();if(o.size()==1&&o.has("param")){String key=o.get("param").getAsString();if(!args.has(key))throw new IllegalArgumentException("missing_parameter_"+key);return args.get(key).deepCopy();}if(o.size()==1&&o.has("context")){MinecraftContext c=new MinecraftContext();return c.get(o.get("context").getAsString());}JsonObject r=new JsonObject();o.entrySet().forEach(e->r.add(e.getKey(),bind(e.getValue(),args)));return r;}if(value.isJsonArray()){JsonArray r=new JsonArray();value.getAsJsonArray().forEach(v->r.add(bind(v,args)));return r;}return value.deepCopy();}
 private static class MinecraftContext {JsonElement get(String key){var mc=net.minecraft.client.Minecraft.getInstance();return switch(key){case "menu_id"->new JsonPrimitive(mc.player.containerMenu.containerId);case "menu_state_id"->new JsonPrimitive(mc.player.containerMenu.getStateId());case "player_uuid"->new JsonPrimitive(mc.player.getUUID().toString());default->throw new IllegalArgumentException("unknown_context_key");};}}
 private static String hash(Path p)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(var stream=Files.newInputStream(p)){byte[] b=new byte[65536];int n;while((n=stream.read(b))!=-1)digest.update(b,0,n);}return HexFormat.of().formatHex(digest.digest());}
}
